import type { Actor } from \"@/types/member\";

/** Project IDs visible to an actor, usable in listing queries before pagination. */
export function visibleProjectIds(actor: Actor) {
  const db = getDb();
  const membership = db.select({ id: projectMembers.projectId }).from(projectMembers).where(
    and(eq(projectMembers.orgId, actor.orgId), eq(projectMembers.userId, actor.userId)),
  );
  return db.select({ id: projects.id }).from(projects).where(and(
    eq(projects.orgId, actor.orgId),
    actor.isPlatformStaff || hasRoleAtLeast(actor.role, \"admin\")
      ? undefined
      : or(eq(projects.visibility, \"org\"), eq(projects.visibility, \"public\"), eq(projects.leadId, actor.userId), inArray(projects.id, membership)),
  ));
}
